export interface CityData {
  countryCode: string
  name: string
  normalized: string
  lat?: number
  lon?: number
  population?: number
}

function normalize(name: string): string {
  return name
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, "")
}

